// Supertype unions
export type Statement =
	| SimpleStatements
	| CompoundStatement
	| IfStatement
	| ForStatement
	| WhileStatement
	| TryStatement
	| WithStatement
	| FunctionDefinition
	| ClassDefinition
	| DecoratedDefinition
	| MatchStatement;

export type StatementTree =
	| SimpleStatementsTree
	| IfStatementTree
	| ForStatementTree
	| WhileStatementTree
	| TryStatementTree
	| WithStatementTree
	| FunctionDefinitionTree
	| ClassDefinitionTree
	| DecoratedDefinitionTree
	| MatchStatementTree;

export type SimpleStatement =
	| FutureImportStatement
	| ImportStatement
	| ImportFromStatement
	| PrintStatement
	| AssertStatement
	| ExpressionStatement
	| ReturnStatement
	| DeleteStatement
	| RaiseStatement
	| PassStatement
	| BreakStatement
	| ContinueStatement
	| GlobalStatement
	| NonlocalStatement
	| ExecStatement
	| TypeAliasStatement;

export type SimpleStatementTree =
	| FutureImportStatementTree
	| ImportStatementTree
	| ImportFromStatementTree
	| PrintStatementTree
	| AssertStatementTree
	| ExpressionStatementTree
	| ReturnStatementTree
	| DeleteStatementTree
	| RaiseStatementTree
	| PassStatementTree
	| BreakStatementTree
	| ContinueStatementTree
	| GlobalStatementTree
	| NonlocalStatementTree
	| ExecStatementTree
	| TypeAliasStatementTree;

